00081 // ---------------------------------------------------------------------------
00082 template <typename Type>
00083 AI_FORCE_INLINE aiReturn aiMaterial::Get(const char* pKey,unsigned int type,
00084         unsigned int idx, Type* pOut,
00085         unsigned int* pMax) const {
00086     unsigned int iNum = pMax ? *pMax : 1;
00087 
00088     const aiMaterialProperty* prop;
00089     const aiReturn ret = ::aiGetMaterialProperty(this,pKey,type,idx,
00090         (const aiMaterialProperty**)&prop);
00091     if ( AI_SUCCESS == ret )    {
00092 
00093         if (prop->mDataLength < sizeof(Type)*iNum) {
00094             return AI_FAILURE;
00095         }
00096 
00097         if (prop->mType != aiPTI_Buffer) {
00098             return AI_FAILURE;
00099         }
00100 
00101         iNum = static_cast<unsigned int>(std::min(static_cast<size_t>(iNum),prop->mDataLength / sizeof(Type)));
00102         ::memcpy(pOut,prop->mData,iNum * sizeof(Type));
00103         if (pMax) {
00104             *pMax = iNum;
00105         }
00106     }
00107     return ret;
00108 }
00109 
00110 // ---------------------------------------------------------------------------
00111 template <typename Type>
00112 AI_FORCE_INLINE aiReturn aiMaterial::Get(const char* pKey,unsigned int type,
00113         unsigned int idx,Type& pOut) const {
00114     const aiMaterialProperty* prop;
00115     const aiReturn ret = ::aiGetMaterialProperty(this,pKey,type,idx,
00116         (const aiMaterialProperty**)&prop);
00117     if ( AI_SUCCESS == ret ) {
00118 
00119         if (prop->mDataLength < sizeof(Type)) {
00120             return AI_FAILURE;
00121         }
00122 
00123         if (prop->mType != aiPTI_Buffer) {
00124             return AI_FAILURE;
00125         }
00126 
00127         ::memcpy( &pOut, prop->mData, sizeof( Type ) );
00128     }
00129     return ret;
00130 }
