00132 // ---------------------------------------------------------------------------
00133 // Specialisation for a single bool.
00134 // Casts floating point and integer to bool
00135 template <>
00136 AI_FORCE_INLINE
00137         aiReturn
00138         aiMaterial::Get(const char *pKey, unsigned int type,
00139                 unsigned int idx, bool &pOut) const {
00140     const aiMaterialProperty *prop;
00141     const aiReturn ret = ::aiGetMaterialProperty(this, pKey, type, idx,
00142             (const aiMaterialProperty **)&prop);
00143     if (AI_SUCCESS == ret) {
00144 
00145         switch (prop->mType) {
00146             // Type cannot be converted
00147         default: return AI_FAILURE;
00148 
00149         case aiPTI_Buffer: {
00150             // Native bool value storage
00151             if (prop->mDataLength < sizeof(bool)) {
00152                 return AI_FAILURE;
00153             }
00154             ::memcpy(&pOut, prop->mData, sizeof(bool));
00155         } break;
00156 
00157         case aiPTI_Float:
00158         case aiPTI_Double: {
00159             // Read as float and cast to bool
00160             ai_real value = 0.0f;
00161             if (AI_SUCCESS == ::aiGetMaterialFloat(this, pKey, type, idx, &value)) {
00162                 pOut = static_cast<bool>(value);
00163                 return AI_SUCCESS;
00164             }
00165             return AI_FAILURE;
00166         }
00167         case aiPTI_Integer: {
00168             // Cast to bool
00169             const int value = static_cast<int>(*prop->mData);
00170             pOut = static_cast<bool>(value);
00171             return AI_SUCCESS;
00172         }
00173         }
00174     }
00175     return ret;
00176 }
